// Student.javaclass Student {    // Attributes    String name;    int rollNumber;    double marks;    String grade;    // Constructor    Student(String name, int rollNumber, double marks) {        this.name = name;        this.rollNumber = rollNumber;        this.marks = marks;        this.grade = calculateGrade();  // Calculate grade at the time of object creation    }    // Method to calculate grade based on marks    String calculateGrade() {        if (marks >= 90) {            return "A";        } else if (marks >= 80) {            return "B";        } else if (marks >= 70) {            return "C";        } else if (marks >= 60) {            return "D";        } else {            return "F";        }    }    // Method to display student details and grade    void displayDetails() {        System.out.println("Student Details:");        System.out.println("Name: " + name);        System.out.println("Roll Number: " + rollNumber);        System.out.println("Marks: " + marks);        System.out.println("Grade: " + grade);    }}// Main class to test Student classpublic class StudentReport {    public static void main(String[] args) {        // Create Student object        Student student1 = new Student("Alice", 101, 85.5);        // Display details        student1.displayDetails();    }}